'use strict';

// MODULES //

var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var isNegativeZerof = require( '@stdlib/math/base/assert/is-negative-zerof' );
var isIntegerf = require( '@stdlib/math/base/assert/is-integerf' );
var floorf = require( '@stdlib/math/base/special/floorf' );
var sinf = require( '@stdlib/math/base/special/sinf' );
var PINF = require( '@stdlib/constants/float32/pinf' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var PI = require( '@stdlib/constants/float32/pi' );
var smallApprox = require( './small_approximation.js' );
var polyeval = require( './polyval_p.js' );

// var stirlingApprox = require( './stirling_approximation.js' );


// VARIABLES //

var ZERO = f32( 0.0 );
var HALF = f32( 0.5 );
var ONE = f32( 1.0 );
var TWO = f32( 2.0 );
var THREE = f32( 3.0 );
var MAX_ARG = f32( 34.84425627277176174 );
var MIN_ARG = f32( -34.1955451965332 );
var SMALL_X = f32( 1.0e-4 );

// var TEN = f32( 10 );

// MAIN //

/**
* Evaluates the gamma function of a single-precision floating-point number.
*
* ## Method
*
* 1.  Arguments between 0 and 10 are reduced by recurrence and the function is approximated by a polynomial function covering the interval (2,3)
* 2.  Large arguments are handled by Stirling's formula.
* 3.  Negative arguments are made positive using a reflection formula.
*
* ## Notes
*
* -   Relative error:
*
*     | arithmetic | domain    | # trials | peak    | rms     |
*     |:----------:|:---------:|:--------:|:-------:|:-------:|
*     | IEEE       | 0,-33     | 100,000  | 5.7e-7  | 1.0e-7  |
*     | IEEE       | -33,0     | 100,000  | 6.1e-7  | 1.2e-7  |
*
* @param {number} x - input value
* @returns {number} function value
*
* @example
* var v = gammaf( 4.0 );
* // returns 6.0
*
*/
function gammaf( x ) {
	var direction;
	var negative;
	var small;
	var sign;
	var nz;
	var q;
	var p;
	var z;

	x = f32( x );

	if ( ( isIntegerf( x ) && x < 0 ) || isnanf( x ) || x === NINF ) {
		return NaN;
	}

	if ( x === ZERO ) {
		if ( isNegativeZerof( x ) ) {
			return NINF;
		}
		return PINF;
	}

	if ( x > MAX_ARG ) {
		return PINF;
	}

	if ( x < MIN_ARG ) {
		return 0.0;
	}

	if ( x < ZERO ) {
		negative = 1;
		q = -x;
		p = floorf( q );
		if ( p === q ) {
			return NaN;
		}
		if ( (p&1) === 0 ) {
			sign = -ONE;
		} else {
			sign = ONE;
		}
		nz = f32( q - p );
		if ( nz > HALF ) {
			p += ONE;
			nz = f32( q - p );
		}
		nz = f32( q * sinf( f32( PI * nz ) ) );
		if ( nz === ZERO ) {
			return NaN;
		}
		if ( nz < 0 ) {
			nz = f32( -nz );
		}
		x = f32( q );
	}
	// if ( x >= TEN ) {
	// 	z = stirlingApprox( x );
	// }
	if ( x < TWO ) {
		direction = 1;
	} else {
		direction = 0;
	}
	z = ONE;
	while ( x >= THREE ) {
		x = f32( x - ONE );
		z = f32( z * x );
	}
	small = 0;
	while ( x < TWO ) {
		if ( x < SMALL_X ) {
			small = 1;
			break;
		}
		z = f32( z * x );
		x = f32( x + ONE );
	}

	if ( small ) {
		if ( x === ZERO ) {
			return PINF;
		}
		p = smallApprox( x, z );
	} else {
		if ( direction ) {
			z = f32( ONE / z );
		}
		if ( x === TWO ) {
			p = z;
		} else {
			x = f32( x - TWO );
			p = f32( z * polyeval( x ) );
		}
	}
	if ( negative ) {
		p = f32( f32( sign * PI ) / f32( nz * p ) );
	}
	return p;
}


// EXPORTS //

module.exports = gammaf;
